INSERT INTO "champions" VALUES('TFT17_Bard','17.1b','Bard',5,'APCaster','ASSETS/Characters/TFT17_Bard/Skins/Base/Images/TFT17_Bard_splash_centered_8.TFT_Set17.tex','ASSETS/Characters/TFT17_Bard/Skins/Base/Images/TFT17_Bard_splash_tile_8.TFT_Set17.tex','ASSETS/Characters/TFT17_Bard/HUD/TFT17_Bard_Square.TFT_Set17.tex','[{"apiName":"TFT17_Astronaut","name":"Meeple"},{"apiName":"TFT17_ManaTrait","name":"Conduit"}]','{"armor":40,"attackSpeed":0.8500000238418579,"critChance":0.25,"critMultiplier":1.399999976158142,"damage":30,"hp":900,"initialMana":0,"magicResist":40,"mana":65,"range":4}','{"desc":"Summon a flying saucer over the current target that lasts 4 seconds. Each second it deals <magicDamage>[ 220 / 330 / 3000 ]&nbsp;(%i:scaleAP%)</magicDamage>&nbsp;magic damage to the target, plus <magicDamage>[ 135 / 205 / 1500 ]&nbsp;(%i:scaleAP%)</magicDamage>&nbsp;magic damage split between all enemies within 1&nbsp;hex. The saucer deals <TFTBonus>30%</TFTBonus> increased damage to Tanks.<br><br>If an enemy under the UFO dies, Bard has a <TFTBonus>[ 15 / 20 / 100 ]%&nbsp;</TFTBonus>chance to abduct them and create a 1-star copy on your bench.<br><br><mainText enabled=TFT17_Astronaut_IsActive alternate=rules><spellActive enabled=TFT17_Astronaut_IsActive alternate=rules>Meep bonus:</spellActive> On combat start, grant the nearest <TFTBonus>1</TFTBonus>&nbsp;(%i:set14AmpIcon%) Meeple allies an additional Meep.</mainText><br><br><rules>Friends abducted: @TFTUnitProperty.:TFT17_Bard_FriendsAbducted@</rules>","icon":"ASSETS/Characters/TFT17_Bard/HUD/Icons2D/TFT17_Bard_E.TFT_Set17.tex","name":"Ultra Friendly Object","variables":[{"name":"DamagePerSecond","value":[2,220,330,3000,5000,2,2]},{"name":"SplitDamagePerSecond","value":[0,135,205,1500,2500,0,0]},{"name":"Duration","value":[4,4,4,4,4,4,4]},{"name":"AbductChance","value":[0.4,0.15,0.2,1,0.4,0.4,0.4]},{"name":"PVEAbductionChanceModifier","value":[1,1,1,1,1,1,1]},{"name":"MeepsPerMeep","value":[1,1,1,1,1,1,1]},{"name":"TankDamageIncrease","value":[0.3,0.3,0.3,0.3,0.3,0.3,0.3]},{"name":"SecondaryHexRange","value":[1,1,1,1,1,1,1]},{"name":"CanAbductSecondaryTargets","value":[1,1,1,1,1,1,1]},{"name":"ModifiedDamagePerSecond","value":[2,220,330,3000,5000,2,2]},{"name":"ModifiedSplitDamagePerSecond","value":[0,135,205,1500,2500,0,0]},{"name":"TankDamageIncrease*100","value":[30,30,30,30,30,30,30]},{"name":"AbductChance*100","value":[40,15,20,100,40,40,40]},{"name":"ModifiedNumAllies","value":[1,1,1,1,1,1,1]},{"name":"TFTUnitProperty.:TFT17_Bard_FriendsAbducted","value":[0,0,0,0]}]}','{"ability":{"desc":"Summon a flying saucer over the current target that lasts 4 seconds. Each second it deals <magicDamage>[ 220 / 330 / 3000 ]&nbsp;(%i:scaleAP%)</magicDamage>&nbsp;magic damage to the target, plus <magicDamage>[ 135 / 205 / 1500 ]&nbsp;(%i:scaleAP%)</magicDamage>&nbsp;magic damage split between all enemies within 1&nbsp;hex. The saucer deals <TFTBonus>30%</TFTBonus> increased damage to Tanks.<br><br>If an enemy under the UFO dies, Bard has a <TFTBonus>[ 15 / 20 / 100 ]%&nbsp;</TFTBonus>chance to abduct them and create a 1-star copy on your bench.<br><br><mainText enabled=TFT17_Astronaut_IsActive alternate=rules><spellActive enabled=TFT17_Astronaut_IsActive alternate=rules>Meep bonus:</spellActive> On combat start, grant the nearest <TFTBonus>1</TFTBonus>&nbsp;(%i:set14AmpIcon%) Meeple allies an additional Meep.</mainText><br><br><rules>Friends abducted: @TFTUnitProperty.:TFT17_Bard_FriendsAbducted@</rules>","icon":"ASSETS/Characters/TFT17_Bard/HUD/Icons2D/TFT17_Bard_E.TFT_Set17.tex","name":"Ultra Friendly Object","variables":[{"name":"DamagePerSecond","value":[2,220,330,3000,5000,2,2]},{"name":"SplitDamagePerSecond","value":[0,135,205,1500,2500,0,0]},{"name":"Duration","value":[4,4,4,4,4,4,4]},{"name":"AbductChance","value":[0.4,0.15,0.2,1,0.4,0.4,0.4]},{"name":"PVEAbductionChanceModifier","value":[1,1,1,1,1,1,1]},{"name":"MeepsPerMeep","value":[1,1,1,1,1,1,1]},{"name":"TankDamageIncrease","value