INSERT INTO "champions" VALUES('TFT17_Urgot','17.1b','Urgot',3,'ADFighter','ASSETS/Characters/TFT17_Urgot/Skins/Base/Images/TFT17_Urgot_splash_centered_32.TFT_Set17.tex','ASSETS/Characters/TFT17_Urgot/Skins/Base/Images/TFT17_Urgot_splash_tile_32.TFT_Set17.tex','ASSETS/Characters/TFT17_Urgot/HUD/TFT17_Urgot_Square.TFT_Set17.tex','[{"apiName":"TFT17_Mecha","name":"Mecha"},{"apiName":"TFT17_HPTank","name":"Brawler"},{"apiName":"TFT17_MeleeTrait","name":"Marauder"}]','{"armor":45,"attackSpeed":0.800000011920929,"critChance":0.25,"critMultiplier":1.399999976158142,"damage":60,"hp":600,"initialMana":0,"magicResist":45,"mana":50,"range":2}','{"desc":"<spellPassive>Passive - Proximity Blast:</spellPassive> Whenever an enemy enters a <TFTBonus>2 (%i:scaleRange%)</TFTBonus> hex radius, fire a blast in a cone towards the closest adjacent hex that deals <physicalDamage>[ 85 / 125 / 200 ]&nbsp;(%i:scaleAD%)</physicalDamage> physical damage with 30% falloff per hex. Each adjacent hex has a 5 second cooldown, and starts combat on cooldown.<br><br><spellActive>Active:</spellActive> Gain <TFTBonus>[ 150 / 175 / 200 ]&nbsp;(%i:scaleAP%)</TFTBonus> Shield for 3 seconds and reposition up to one hex to maximize the number of targets within Proximity Blast''s radius. Reset Proximity Blast''s cooldowns.","icon":"ASSETS/Characters/TFT17_Urgot/HUD/Icons2D/TFT17_Urgot_E.TFT_Set17.tex","name":"Unstoppable Dreadnought","variables":[{"name":"ShotgunDamage","value":[90,85,125,200,275,1.8,1.8]},{"name":"ShotgunCooldown","value":[5,5,5,5,5,5,5]},{"name":"ShieldAmount","value":[200,150,175,200,225,420,420]},{"name":"ShieldDuration","value":[3,3,3,3,3,3,3]},{"name":"FalloffPerHex","value":[0.3,0.3,0.3,0.3,0.3,0.3,0.3]},{"name":"ShotgunRange","value":[2,2,2,2]},{"name":"ModifiedShotgunDamage","value":[90,85,125,200,275,1.8,1.8]},{"name":"FalloffPerHex*100","value":[30,30,30,30,30,30,30]},{"name":"ModifiedShield","value":[200,150,175,200,225,420,420]}]}','{"ability":{"desc":"<spellPassive>Passive - Proximity Blast:</spellPassive> Whenever an enemy enters a <TFTBonus>2 (%i:scaleRange%)</TFTBonus> hex radius, fire a blast in a cone towards the closest adjacent hex that deals <physicalDamage>[ 85 / 125 / 200 ]&nbsp;(%i:scaleAD%)</physicalDamage> physical damage with 30% falloff per hex. Each adjacent hex has a 5 second cooldown, and starts combat on cooldown.<br><br><spellActive>Active:</spellActive> Gain <TFTBonus>[ 150 / 175 / 200 ]&nbsp;(%i:scaleAP%)</TFTBonus> Shield for 3 seconds and reposition up to one hex to maximize the number of targets within Proximity Blast''s radius. Reset Proximity Blast''s cooldowns.","icon":"ASSETS/Characters/TFT17_Urgot/HUD/Icons2D/TFT17_Urgot_E.TFT_Set17.tex","name":"Unstoppable Dreadnought","variables":[{"name":"ShotgunDamage","value":[90,85,125,200,275,1.8,1.8]},{"name":"ShotgunCooldown","value":[5,5,5,5,5,5,5]},{"name":"ShieldAmount","value":[200,150,175,200,225,420,420]},{"name":"ShieldDuration","value":[3,3,3,3,3,3,3]},{"name":"FalloffPerHex","value":[0.3,0.3,0.3,0.3,0.3,0.3,0.3]},{"name":"ShotgunRange","value":[2,2,2,2]},{"name":"ModifiedShotgunDamage","value":[90,85,125,200,275,1.8,1.8]},{"name":"FalloffPerHex*100","value":[30,30,30,30,30,30,30]},{"name":"ModifiedShield","value":[200,150,175,200,225,420,420]}]},"apiName":"TFT17_Urgot","characterName":"TFT17_Urgot","cost":3,"icon":"ASSETS/Characters/TFT17_Urgot/Skins/Base/Images/TFT17_Urgot_splash_centered_32.TFT_Set17.tex","name":"Urgot","role":"ADFighter","squareIcon":"ASSETS/Characters/TFT17_Urgot/Skins/Base/Images/TFT17_Urgot_splash_tile_32.TFT_Set17.tex","stats":{"armor":45,"attackSpeed":0.800000011920929,"critChance":0.25,"critMultiplier":1.399999976158142,"damage":60,"hp":600,"initialMana":0,"magicResist":45,"mana":50,"range":2},"tileIcon":"ASSETS/Characters/TFT17_Urgot/HUD/TFT17_Urgot_Square.TFT_Set17.tex","traits":[{"apiName":"TFT17_Mecha","name":"Mecha"},{"apiName":"TFT17_HPTank","name":"Brawler"},{"apiName":"TFT17_MeleeTrait","name":"Marauder"}],"org":{"ability":{