INSERT INTO "items" VALUES('TFT17_Item_Artifact_EvelynnArtifact','17.1b','Evelynn''s Instinct',NULL,'ASSETS/Maps/TFT/Icons/Items/Hexcore/TFT17_Item_Artifact_EvelynnFang.TFT_Set17.tex','null','{"AD":0.10000000149011612,"AP":10,"AS":40,"DecayingAS":0.5,"Duration":3,"ExecuteThresholdForTarget":0.11999999731779099,"StatOmnivamp":0.15000000596046448}','{"apiName":"TFT17_Item_Artifact_EvelynnArtifact","associatedTraits":[],"composition":[],"desc":"When switching targets, blink to the next target. Attacks and Abilities execute the holder''s target below 12% of their Health.<br><br>Kills grant the holder 50% Attack Speed decaying over 3 seconds.<br>","effects":{"AD":0.10000000149011612,"AP":10,"AS":40,"DecayingAS":0.5,"Duration":3,"ExecuteThresholdForTarget":0.11999999731779099,"StatOmnivamp":0.15000000596046448},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Items/Hexcore/TFT17_Item_Artifact_EvelynnFang.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"Evelynn''s Instinct","tags":["{44ace175}","{ec243f6b}"],"unique":false,"category":"artifact","org":{"desc":"When switching targets, blink to the next target. Attacks and Abilities execute the holder''s target below @ExecuteThresholdForTarget*100@% of their Health.<br><br>Kills grant the holder @DecayingAS*100@% Attack Speed decaying over @Duration@ seconds.<br>","effects":{"AD":0.10000000149011612,"AP":10,"AS":40,"DecayingAS":0.5,"Duration":3,"ExecuteThresholdForTarget":0.11999999731779099,"StatOmnivamp":0.15000000596046448}},"_key":"TFT17_Item_Artifact_EvelynnArtifact","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-item/TFT17_Item_Artifact_EvelynnArtifact.png","removeSpaceName":"Evelynn''sInstinct"}');
