INSERT INTO "items" VALUES('TFT_Item_TitanicHydra','17.1b','Zz''Rot Portal',NULL,'ASSETS/Maps/TFT/Icons/Items/Hexcore/TFT_Item_TitanicHydra.TFT_Set13.tex','null','{"AS":10,"Health":150,"SummonedStatReduction":25}','{"apiName":"TFT_Item_TitanicHydra","associatedTraits":[],"composition":[],"desc":"Combat start: <TFTKeyword>Taunt</TFTKeyword>.<br>On death, a Voidspawn arises, <TFTKeyword>Taunting</TFTKeyword> nearby enemies. The Voidspawn has massively reduced effectiveness when created by a summoned unit.<br><br><tftitemrules><tftbold>Taunt</tftbold>: enemies that are able and in range must attack the taunter</tftitemrules>","effects":{"AS":10,"Health":150,"SummonedStatReduction":25},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Items/Hexcore/TFT_Item_TitanicHydra.TFT_Set13.tex","id":null,"incompatibleTraits":[],"name":"Zz''Rot Portal","tags":[],"unique":false,"org":{"desc":"Combat start: <TFTKeyword>Taunt</TFTKeyword>.<br>On death, a Voidspawn arises, <TFTKeyword>Taunting</TFTKeyword> nearby enemies. The Voidspawn has massively reduced effectiveness when created by a summoned unit.<br><br><tftitemrules><tftbold>Taunt</tftbold>: enemies that are able and in range must attack the taunter</tftitemrules>","effects":{"AS":10,"Health":150,"SummonedStatReduction":25}},"_key":"TFT_Item_TitanicHydra","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-item/TFT_Item_TitanicHydra.png","specialEffects":["Taunt"],"removeSpaceName":"Zz''RotPortal"}');
INSERT INTO "items" VALUES('TFT17_Item_Artifact_AhriArtifact','17.1b','Ahri''s Aura',NULL,'ASSETS/Maps/TFT/Icons/Items/Hexcore/TFT17_Item_Artifact_AhriRhythm.TFT_Set17.tex','null','{"AP":20,"FlatMagicDamage":50,"ManaRegen":4,"ManaSpent":20,"PercentSpeedIncrease":0.05000000074505806}','{"apiName":"TFT17_Item_Artifact_AhriArtifact","associatedTraits":[],"composition":[],"desc":"The holder is orbited by 3 foxfires. Each one deals <magicDamage>50&nbsp;(%i:scaleAP%)</magicDamage> magic damage and the orbit expands to hit the holder''s current target.<br><br>For every 20 Mana the holder spends, foxfires travel 5% faster for the rest of combat.","effects":{"AP":20,"FlatMagicDamage":50,"ManaRegen":4,"ManaSpent":20,"PercentSpeedIncrease":0.05000000074505806},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Items/Hexcore/TFT17_Item_Artifact_AhriRhythm.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"Ahri''s Aura","tags":["{44ace175}","{ec243f6b}"],"unique":false,"category":"artifact","org":{"desc":"The holder is orbited by 3 foxfires. Each one deals <magicDamage>@FlatMagicDamage@&nbsp;(%i:scaleAP%)</magicDamage> magic damage and the orbit expands to hit the holder''s current target.<br><br>For every @ManaSpent@ Mana the holder spends, foxfires travel @PercentSpeedIncrease*100@% faster for the rest of combat.","effects":{"AP":20,"FlatMagicDamage":50,"ManaRegen":4,"ManaSpent":20,"PercentSpeedIncrease":0.05000000074505806}},"_key":"TFT17_Item_Artifact_AhriArtifact","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-item/TFT17_Item_Artifact_AhriArtifact.png","balance":-1,"diff":{"effects":["FlatMagicDamage"]},"removeSpaceName":"Ahri''sAura"}');
INSERT INTO "items" VALUES('TFT9_Item_CrownOfDemacia','17.1b','Crown of Demacia',NULL,'ASSETS/Maps/Particles/TFT/Item_Icons/TFT9_RegionItems/CrownOfDemacia.tex','null','{"ADandAPPerTick":10,"AS":30,"HealTickRate":2,"HealingPercentPerTickPerStage":3,"Health":300}','{"apiName":"TFT9_Item_CrownOfDemacia","associatedTraits":[],"composition":[],"desc":"If the holder is a Tank, regenerate 3-21% maximum Health every 2 seconds (based on stage). Otherwise, gain 10% %i:scaleAD% Attack Damage and %i:scaleAP% Ability Power every 2 seconds instead. <br><br>If the holder of this item dies, you instantly lose the fight.<br><br><tftitemrules>You can remove this item by benching the holder.</tftitemrules><br><br>","effects":{"ADandAPPerTick":10,"AS":30,"HealTickRate":2,"HealingPercentPerTickPerStage":3,"Health":300},"from":null,"icon":"ASSETS/Maps/Particles/TFT/Item_Icons/TFT9_RegionItems/CrownOfDemacia.tex","id":null,"incompatibleTraits":[],"name":"Crown of Demacia","tags":["{d8d00bcc}"],"unique":true,"category":null,"org":{"desc":"If the holder is a Tank, regenerate @HealingPercentPerTickPerStage@-@HealingPercentPerTickPerStage*7@% maximum Health every @HealTickRate@ seconds (based on stage). Otherwise, gain @ADandAPPerTick@% %i:scaleAD% Attack Damage and %i:scaleAP% Ability Power every @HealTickRate@ seconds instead. <br><br>If the holder of this item dies, you instantly lose the fight.<br><br><tftitemrules>You can remove this item by benching the holder.</tftitemrules><br><br>","effects":{"ADandAPPerTick":10,"AS":30,"HealTickRate":2,"HealingPercentPerTickPerStage":3,"Health":300}},"_key":"TFT9_Item_CrownOfDemacia","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-item/TFT9_Item_CrownOfDemacia.png","removeSpaceName":"CrownofDemacia"}');
