INSERT INTO "traits" VALUES('TFT17_VexUniqueTrait','17.1b','Doomer','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Doomer.TFT_Set17.tex','Combat Start: Mark all enemies with Doom.<br>','[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"ADAP1":12}}]','{"apiName":"TFT17_VexUniqueTrait","desc":"Combat Start: Mark all enemies with Doom.<br>","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"ADAP1":12}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Doomer.TFT_Set17.tex","name":"Doomer","org":{"desc":"Combat Start: Mark all enemies with Doom.<br><br>The first time enemies are damaged each combat, their Doom is consumed, stealing @ADAP1@% Attack Damage and Ability Power from them and granting it to your strongest Vex.","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"ADAP1":12}}]},"_key":"TFT17_VexUniqueTrait","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_Doomer.TFT_Set17.png","champions":[{"apiName":"TFT17_Vex","name":"Vex"}],"category":"origin","removeSpaceName":"Doomer"}');
INSERT INTO "traits" VALUES('TFT17_ASTrait','17.1b','Challenger','class','ASSETS/UX/TraitIcons/Trait_Icon_17_Challenger.TFT_Set17.tex','Your team gains 10% Attack Speed. Challengers gain bonus Attack Speed. When their target dies, Challengers dash to a new target and increase their Attack Speed bonus by 50% for 2.5 seconds.<br>','[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"AttackSpeedPercent":0.15,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.1}},{"maxUnits":3,"minUnits":3,"style":3,"variables":{"AttackSpeedPercent":0.22,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.1}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"AttackSpeedPercent":0.4,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.1}},{"maxUnits":25000,"minUnits":5,"style":4,"variables":{"AttackSpeedPercent":0.55,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.1}}]','{"apiName":"TFT17_ASTrait","desc":"Your team gains 10% Attack Speed. Challengers gain bonus Attack Speed. When their target dies, Challengers dash to a new target and increase their Attack Speed bonus by 50% for 2.5 seconds.<br>","effects":[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"AttackSpeedPercent":0.15,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.1}},{"maxUnits":3,"minUnits":3,"style":3,"variables":{"AttackSpeedPercent":0.22,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.1}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"AttackSpeedPercent":0.4,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.1}},{"maxUnits":25000,"minUnits":5,"style":4,"variables":{"AttackSpeedPercent":0.55,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.1}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Challenger.TFT_Set17.tex","name":"Challenger","org":{"desc":"Your team gains @TeamwideAS*100@% Attack Speed. Challengers gain bonus Attack Speed. When their target dies, Challengers dash to a new target and increase their Attack Speed bonus by @BurstPercent*100@% for @BurstDuration@ seconds.<br><br><row>(@MinUnits@) @AttackSpeedPercent*100@%&nbsp;%i:scaleAS%</row><br><row>(@MinUnits@) @AttackSpeedPercent*100@%&nbsp;%i:scaleAS%</row><br><row>(@MinUnits@) @AttackSpeedPercent*100@%&nbsp;%i:scaleAS%</row><br><row>(@MinUnits@) @AttackSpeedPercent*100@%&nbsp;%i:scaleAS%</row>","effects":[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"AttackSpeedPercent":0.15000000596046448,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.10000000149011612}},{"maxUnits":3,"minUnits":3,"style":3,"variables":{"AttackSpeedPercent":0.2199999988079071,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.10000000149011612}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"AttackSpeedPercent":0.4000000059604645,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.10000000149011612}},{"maxUnits":25000,"minUnits":5,"style":5,"variables":{"AttackSpeedPercent":0.550000011920929,"BurstDuration":2.5,"BurstPercent":0.5,"DamageReduction":null,"TeamwideAS":0.10000000149011612}}]},"_key":"TFT17_ASTrait","level":{"2":"15%&nbsp;%i:scaleAS%","3":"22%&nbsp;%i:scaleAS%","4":"40%&nbsp;%i:scaleAS%","5":"55%&nbsp;%i:scaleAS%"},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_Challenger.TFT_Set17.png","champions":[{"apiName":"TFT17_Belveth","name":"Bel''Veth"},{"apiName":"TFT17_Jinx","name":"Jinx"},{"apiName":"TFT17_Kindred","name":"Kindred"},{"apiName":"TFT17_Diana","name":"Diana"}],"category":"class","balance":1,"diff":{"effects.variables":["AttackSpeedPercent%"]},"removeSpaceName":"Challenger"}');
INSERT INTO "traits" VALUES('TFT17_MissFortuneUndeterminedTrait','17.1b','Choose Trait',NULL,'ASSETS/UX/TraitIcons/Trait_Icon_17_MissFortuneUndetermindedTrait.TFT_Set17.tex','When you field Miss Fortune, choose between Conduit Mode, Challenger Mode, and Replicator Mode. Miss Fortune has a unique ability based on her mode and gains the associated trait.','[]','{"apiName":"TFT17_MissFortuneUndeterminedTrait","desc":"When you field Miss Fortune, choose between Conduit Mode, Challenger Mode, and Replicator Mode. Miss Fortune has a unique ability based on her mode and gains the associated trait.","effects":[],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_MissFortuneUndetermindedTrait.TFT_Set17.tex","name":"Choose Trait","org":{"desc":"When you field Miss Fortune, choose between Conduit Mode, Challenger Mode, and Replicator Mode. Miss Fortune has a unique ability based on her mode and gains the associated trait.","effects":[]},"_key":"TFT17_MissFortuneUndeterminedTrait","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_MissFortuneUndetermindedTrait.TFT_Set17.png","champions":[{"apiName":"TFT17_MissFortune","name":"Miss Fortune"}],"removeSpaceName":"ChooseTrait"}');
INSERT INTO "traits" VALUES('TFT17_Stargazer_Wolf','17.1b','Stargazer (The Boar)','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex','Stargazers chart a different constellation every game. This game: <TFTStargazer>The Boar</TFTStargazer>.<br><br>Gain gold after winning player combat. Allies in empowered hexes gain 8% Health, Attack Damage, and Ability Power. Stargazers gain more.<br><br>(Gold Earned: @TFTUnitProperty.trait:TFT17_Stargazer_Wolf_TotalGold@)<br>','[{"maxUnits":3,"minUnits":3,"style":1,"variables":{"Wolf_ADAP":10,"Wolf_Gold":1,"Wolf_Health":0.02,"Wolf_Health_Teamwide":0.08,"undefined":8}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"Wolf_ADAP":15,"Wolf_Gold":2,"Wolf_Health":0.08,"Wolf_Health_Teamwide":0.08,"undefined":8}},{"maxUnits":5,"minUnits":5,"style":3,"variables":{"Wolf_ADAP":25,"Wolf_Gold":4,"Wolf_Health":0.15,"Wolf_Health_Teamwide":0.08,"undefined":8}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"Wolf_ADAP":30,"Wolf_Gold":6,"Wolf_Health":0.22,"Wolf_Health_Teamwide":0.08,"undefined":8}}]','{"apiName":"TFT17_Stargazer_Wolf","desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Boar</TFTStargazer>.<br><br>Gain gold after winning player combat. Allies in empowered hexes gain 8% Health, Attack Damage, and Ability Power. Stargazers gain more.<br><br>(Gold Earned: @TFTUnitProperty.trait:TFT17_Stargazer_Wolf_TotalGold@)<br>","effects":[{"maxUnits":3,"minUnits":3,"style":1,"variables":{"Wolf_ADAP":10,"Wolf_Gold":1,"Wolf_Health":0.02,"Wolf_Health_Teamwide":0.08,"undefined":8}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"Wolf_ADAP":15,"Wolf_Gold":2,"Wolf_Health":0.08,"Wolf_Health_Teamwide":0.08,"undefined":8}},{"maxUnits":5,"minUnits":5,"style":3,"variables":{"Wolf_ADAP":25,"Wolf_Gold":4,"Wolf_Health":0.15,"Wolf_Health_Teamwide":0.08,"undefined":8}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"Wolf_ADAP":30,"Wolf_Gold":6,"Wolf_Health":0.22,"Wolf_Health_Teamwide":0.08,"undefined":8}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex","name":"Stargazer (The Boar)","org":{"desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Boar</TFTStargazer>.<br><br>Gain gold after winning player combat. Allies in empowered hexes gain @Wolf_Health_Teamwide*100@% Health, Attack Damage, and Ability Power. Stargazers gain more.<br><br>(Gold Earned: @TFTUnitProperty.trait:TFT17_Stargazer_Wolf_TotalGold@)<br><br><expandRow>(@MinUnits@) @Wolf_Gold@ gold, @Wolf_Health*100@% %i:scaleHealth%, @Wolf_ADAP@% %i:scaleAD%%i:scaleAP%</expandRow><br><br><rules>More hexes reveal at each player level</rules>","effects":[{"maxUnits":3,"minUnits":3,"style":1,"variables":{"Wolf_ADAP":10,"Wolf_Gold":1,"Wolf_Health":0.019999999552965164,"Wolf_Health_Teamwide":0.07999999821186066,"{f5b00dd5}":8}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"Wolf_ADAP":15,"Wolf_Gold":2,"Wolf_Health":0.07999999821186066,"Wolf_Health_Teamwide":0.07999999821186066,"{f5b00dd5}":8}},{"maxUnits":5,"minUnits":5,"style":3,"variables":{"Wolf_ADAP":25,"Wolf_Gold":4,"Wolf_Health":0.15000000596046448,"Wolf_Health_Teamwide":0.07999999821186066,"{f5b00dd5}":8}},{"maxUnits":25000,"minUnits":6,"style":5,"variables":{"Wolf_ADAP":30,"Wolf_Gold":6,"Wolf_Health":0.2199999988079071,"Wolf_Health_Teamwide":0.07999999821186066,"{f5b00dd5}":8}}]},"_key":"TFT17_Stargazer_Wolf","level":{"3":"1 gold, 2% %i:scaleHealth%, 10% %i:scaleAD%%i:scaleAP%","4":"2 gold, 8% %i:scaleHealth%, 15% %i:scaleAD%%i:scaleAP%","5":"4 gold, 15% %i:scaleHealth%, 25% %i:scaleAD%%i:scaleAP%","6":"6 gold, 22% %i:scaleHealth%, 30% %i:scaleAD%%i:scaleAP%"},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_Stargazer.TFT_Set17.png","champions":[],"category":"origin","removeSpaceName":"Stargazer(TheBoar)"}');
