INSERT INTO "traits" VALUES('TFT17_MissFortuneUniqueTrait','17.1b','Gun Goddess','class','ASSETS/UX/TraitIcons/Trait_Icon_17_GunGoddess.TFT_Set17.tex','When you field Miss Fortune, choose between Conduit Mode, Challenger Mode, and Replicator Mode. Miss Fortune has a unique ability based on her mode and gains the associated trait.','[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"Allies":2,"DamageAmp":0.01,"FlatDamage":100,"Mana":2,"NumAttacks":3}}]','{"apiName":"TFT17_MissFortuneUniqueTrait","desc":"When you field Miss Fortune, choose between Conduit Mode, Challenger Mode, and Replicator Mode. Miss Fortune has a unique ability based on her mode and gains the associated trait.","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"Allies":2,"DamageAmp":0.01,"FlatDamage":100,"Mana":2,"NumAttacks":3}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_GunGoddess.TFT_Set17.tex","name":"Gun Goddess","org":{"desc":"When you field Miss Fortune, choose between Conduit Mode, Challenger Mode, and Replicator Mode. Miss Fortune has a unique ability based on her mode and gains the associated trait.","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"Allies":2,"DamageAmp":0.009999999776482582,"FlatDamage":100,"Mana":2,"NumAttacks":3}}]},"_key":"TFT17_MissFortuneUniqueTrait","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_GunGoddess.TFT_Set17.png","champions":[{"apiName":"TFT17_MissFortune","name":"Miss Fortune"}],"category":"class","diff":{"effects.variables":["Allies"]},"removeSpaceName":"GunGoddess"}');
INSERT INTO "traits" VALUES('TFT17_AnimaSquad','17.1b','Anima','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_AnimaTech.TFT_Set17.tex','After losing a player combat, gain 20 Tech, plus additional Tech equal to 5 times the length of your loss streak. Additionally, gain 2 Tech per Anima takedown.<br><br>Each time Animas get 100 Tech, they prototype new Anima Weapons. You can take them, or save your Tech to get more powerful weapons next time.<br>','[{"maxUnits":5,"minUnits":3,"style":1,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPerDeath_PVE":1,"TechPerKill":2,"TechPerLoss":5,"TechPerLoss_DU":5,"TechPerRound_PVE":20,"undefined":0.85}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPerDeath_PVE":1,"TechPerKill":2,"TechPerLoss":5,"TechPerLoss_DU":5,"TechPerRound_PVE":20,"undefined":0.85}}]','{"apiName":"TFT17_AnimaSquad","desc":"After losing a player combat, gain 20 Tech, plus additional Tech equal to 5 times the length of your loss streak. Additionally, gain 2 Tech per Anima takedown.<br><br>Each time Animas get 100 Tech, they prototype new Anima Weapons. You can take them, or save your Tech to get more powerful weapons next time.<br>","effects":[{"maxUnits":5,"minUnits":3,"style":1,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPerDeath_PVE":1,"TechPerKill":2,"TechPerLoss":5,"TechPerLoss_DU":5,"TechPerRound_PVE":20,"undefined":0.85}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPerDeath_PVE":1,"TechPerKill":2,"TechPerLoss":5,"TechPerLoss_DU":5,"TechPerRound_PVE":20,"undefined":0.85}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_AnimaTech.TFT_Set17.tex","name":"Anima","org":{"desc":"After losing a player combat, gain @TechPerCombat@ Tech, plus additional Tech equal to @TechPerLoss@ times the length of your loss streak. Additionally, gain @TechPerKill@ Tech per Anima takedown.<br><br>Each time Animas get @TechBreakpoint@ Tech, they prototype new Anima Weapons. You can take them, or save your Tech to get more powerful weapons next time.<br><br><row>(@MinUnits@) Start Researching! </row><br><row>(@MinUnits@) After winning a player combat, gain loot!</row>","effects":[{"maxUnits":5,"minUnits":3,"style":1,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPerDeath_PVE":1,"TechPerKill":2,"TechPerLoss":5,"TechPerLoss_DU":5,"TechPerRound_PVE":20,"{18a09431}":0.8500000238418579}},{"maxUnits":25000,"minUnits":6,"style":5,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPerDeath_PVE":1,"TechPerKill":2,"TechPerLoss":5,"TechPerLoss_DU":5,"TechPerRound_PVE":20,"{18a09431}":0.8500000238418579}}]},"_key":"TFT17_AnimaSquad","level":{"3":"Start Researching!","6":"After winning a player combat, gain loot!"},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_AnimaTech.TFT_Set17.png","champions":[{"apiName":"TFT17_Briar","name":"Briar"},{"apiName":"TFT17_Jinx","name":"Jinx"},{"apiName":"TFT17_Illaoi","name":"Illaoi"},{"apiName":"TFT17_Aurora","name":"Aurora"},{"apiName":"TFT17_Fiora","name":"Fiora"}],"category":"origin","diff":{"effects.variables":["TechPerCombat_DU","TechPerDeath_PVE","TechPerLoss_DU","TechPerRound_PVE"]},"removeSpaceName":"Anima"}');
