INSERT INTO "traits" VALUES('TFT17_Stargazer_Huntress','17.1b','Stargazer (The Huntress)','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex','Stargazers chart a different constellation every game. This game: <TFTStargazer>The Huntress</TFTStargazer>.<br><br>Combat Start: Mark the highest Health enemies. <br><br>Allies in empowered hexes gain 15% Attack Speed. Stargazers in empowered hexes gain more and heal for 15% of their max Health when a marked enemy dies.<br>','[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"Huntress_AS":0.12,"Huntress_AS_Teamwide":0.15,"Huntress_Heal":0.15,"NumMarks":3}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"Huntress_AS":0.35,"Huntress_AS_Teamwide":0.15,"Huntress_Heal":0.15,"NumMarks":5}},{"maxUnits":25000,"minUnits":7,"style":4,"variables":{"Huntress_AS":0.55,"Huntress_AS_Teamwide":0.15,"Huntress_Heal":0.15,"NumMarks":7}}]','{"apiName":"TFT17_Stargazer_Huntress","desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Huntress</TFTStargazer>.<br><br>Combat Start: Mark the highest Health enemies. <br><br>Allies in empowered hexes gain 15% Attack Speed. Stargazers in empowered hexes gain more and heal for 15% of their max Health when a marked enemy dies.<br>","effects":[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"Huntress_AS":0.12,"Huntress_AS_Teamwide":0.15,"Huntress_Heal":0.15,"NumMarks":3}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"Huntress_AS":0.35,"Huntress_AS_Teamwide":0.15,"Huntress_Heal":0.15,"NumMarks":5}},{"maxUnits":25000,"minUnits":7,"style":4,"variables":{"Huntress_AS":0.55,"Huntress_AS_Teamwide":0.15,"Huntress_Heal":0.15,"NumMarks":7}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex","name":"Stargazer (The Huntress)","org":{"desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Huntress</TFTStargazer>.<br><br>Combat Start: Mark the highest Health enemies. <br><br>Allies in empowered hexes 