INSERT INTO "traits" VALUES('TFT17_Stargazer_Serpent','17.1b','Stargazer (The Serpent)','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex','Stargazers chart a different constellation every game. This game: <TFTStargazer>The Serpent</TFTStargazer>.<br><br>Allies in empowered hexes gain 5% Durability. Stargazers in empowered hexes gain more and poison enemies, repeating a portion of damage dealt as magic damage over 3 seconds.<br>','[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"Serpent_DR":0.05,"Serpent_DR_Teamwide":0.05,"Serpent_Duration":3,"Serpent_Poison":0.25}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"Serpent_DR":0.1,"Serpent_DR_Teamwide":0.05,"Serpent_Duration":3,"Serpent_Poison":0.4}},{"maxUnits":25000,"minUnits":7,"style":4,"variables":{"Serpent_DR":0.15,"Serpent_DR_Teamwide":0.05,"Serpent_Duration":3,"Serpent_Poison":0.6}}]','{"apiName":"TFT17_Stargazer_Serpent","desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Serpent</TFTStargazer>.<br><br>Allies in empowered hexes gain 5% Durability. Stargazers in empowered hexes gain more and poison enemies, repeating a portion of damage dealt as magic damage over 3 seconds.<br>","effects":[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"Serpent_DR":0.05,"Serpent_DR_Teamwide":0.05,"Serpent_Duration":3,"Serpent_Poison":0.25}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"Serpent_DR":0.1,"Serpent_DR_Teamwide":0.05,"Serpent_Duration":3,"Serpent_Poison":0.4}},{"maxUnits":25000,"minUnits":7,"style":4,"variables":{"Serpent_DR":0.15,"Serpent_DR_Teamwide":0.05,"Serpent_Duration":3,"Serpent_Poison":0.6}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex","name":"Stargazer (The Serpent)","org":{"desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Serpent</TFTStargazer>.<br><br>Allies in empowered hexes gain @Serpent_DR_Teamwide*100@% Durability. Stargazers in empowered hexes gain more and poison enemies, repeating a portion of damage dealt as magic damage over @Serpent_Duration@ seconds.<br><br><expandRow>(@MinUnits@) @Serpent_DR*100@% %i:scaleDR%, @Serpent_Poison*100@% poison damage</expandRow><br><br><rules>More hexes reveal at each player level</rules>","effects":[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"Serpent_DR":0.05000000074505806,"Serpent_DR_Teamwide":0.05000000074505806,"Serpent_Duration":3,"Serpent_Poison":0.25}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"Serpent_DR":0.10000000149011612,"Serpent_DR_Teamwide":0.05000000074505806,"Serpent_Duration":3,"Serpent_Poison":0.4000000059604645}},{"maxUnits":25000,"minUnits":7,"style":5,"variables":{"Serpent_DR":0.15000000596046448,"Serpent_DR_Teamwide":0.05000000074505806,"Serpent_Duration":3,"Serpent_Poison":0.6000000238418579}}]},"_key":"TFT17_Stargazer_Serpent","level":{"3":"5% %i:scaleDR%, 25% poison damage","5":"10% %i:scaleDR%, 40% poison damage","7":"15% %i:scaleDR%, 60% poison damage"},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_Stargazer.TFT_Set17.png","champions":[],"category":"origin","removeSpaceName":"Stargazer(TheSerpent)"}');
INSERT INTO "traits" VALUES('TFT17_Stargazer_Shield','17.1b','Stargazer (The Altar)','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex','Stargazers chart a different constellation every game. This game: <TFTStargazer>The Altar</TFTStargazer>.<br>','[{"maxUnits":25000,"minUnits":3,"style":4,"variables":{"Shield_AS_Teamwide":8,"Shield_CashoutAS":18,"Shield_CashoutHP":20,"Shield_Health_Teamwide":8,"Shield_NumDeaths":60}}]','{"apiName":"TFT17_Stargazer_Shield","desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Altar</TFTStargazer>.<br>","effects":[{"maxUnits":25000,"minUnits":3,"style":4,"variables":{"Shield_AS_Teamwide":8,"Shield_CashoutAS":18,"Shield_CashoutHP":20,"Shield_Health_Teamwide":8,"Shield_NumDeaths":60}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex","name":"Stargazer (The Altar)","org":{"desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Altar</TFTStargazer>.<br><br><row>(@MinUnits@) When ANY champion dies, they are sacrificed to the Altar. Allies in empowered hexes gain @Shield_Health_Teamwide@% Health and @Shield_AS_Teamwide@% Attack Speed.<br><br>After @Shield_NumDeaths@ sacrifices, Stargazers in empowered hexes gain an additional @Shield_CashoutHP@% %i:scaleHealth% and @Shield_CashoutAS@% %i:scaleAS%<br><br>Sacrifices: (@TFTUnitProperty.trait:TFT17_Stargazer_Shield_Deaths@ / @Shield_NumDeaths@)</row><br><br><rules>More hexes reveal at each player level</rules>","effects":[{"maxUnits":25000,"minUnits":3,"style":5,"variables":{"Shield_AS_Teamwide":8,"Shield_CashoutAS":18,"Shield_CashoutHP":20,"Shield_Health_Teamwide":8,"Shield_NumDeaths":60}}]},"_key":"TFT17_Stargazer_Shield","level":{"3":"When ANY champion dies, they are sacrificed to the Altar. Allies in empowered hexes gain 8% Health and 8% Attack Speed.After 60 sacrifices, Stargazers in empowered hexes gain an additional 20% %i:scaleHealth% and 18% %i:scaleAS%Sacrifices: (@TFTUnitProperty.trait:TFT17_Stargazer_Shield_Deaths@ / 60)"},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_Stargazer.TFT_Set17.png","champions":[],"category":"origin","removeSpaceName":"Stargazer(TheAltar)"}');
INSERT INTO "traits" VALUES('TFT17_Stargazer_Fountain','17.1b','Stargazer (The Fountain)','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex','Stargazers chart a different constellation every game. This game: <TFTStargazer>The Fountain</TFTStargazer>.<br><br>Allies in empowered hexes gain 1 Mana Regen. Stargazers in empowered hexes gain more and heal the lowest Health ally with their abilities.<br>','[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"Fountain_HealPercent":0.18,"Fountain_ManaRegen":1,"Fountain_ManaRegen_Teamwide":1}},{"maxUnits":25000,"minUnits":5,"style":4,"variables":{"Fountain_HealPercent":0.25,"Fountain_ManaRegen":5,"Fountain_ManaRegen_Teamwide":1}}]','{"apiName":"TFT17_Stargazer_Fountain","desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Fountain</TFTStargazer>.<br><br>Allies in empowered hexes gain 1 Mana Regen. Stargazers in empowered hexes gain more and heal the lowest Health ally with their abilities.<br>","effects":[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"Fountain_HealPercent":0.18,"Fountain_ManaRegen":1,"Fountain_ManaRegen_Teamwide":1}},{"maxUnits":25000,"minUnits":5,"style":4,"variables":{"Fountain_HealPercent":0.25,"Fountain_ManaRegen":5,"Fountain_ManaRegen_Teamwide":1}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex","name":"Stargazer (The Fountain)","org":{"desc":"Stargazers chart a different constellation every game. This game: <TFTStargazer>The Fountain</TFTStargazer>.<br><br>Allies in empowered hexes gain @Fountain_ManaRegen_Teamwide@ Mana Regen. Stargazers in empowered hexes gain more and heal the lowest Health ally with their abilities.<br><br><row>(@MinUnits@) @Fountain_ManaRegen@ %i:TFTManaRegen%, @Fountain_HealPercent*100@% ability damage heal</row><br><row>(@MinUnits@) @Fountain_ManaRegen@ %i:TFTManaRegen%, @Fountain_HealPercent*100@% ability damage heal</row><br><br><rules>More hexes reveal at each player level</rules>","effects":[{"m