INSERT INTO "traits" VALUES('TFT17_AssassinTrait','17.1b','Rogue','class','ASSETS/UX/TraitIcons/Trait_Icon_17_Rogue.TFT_Set17.tex','Rogues gain Attack Damage and Ability Power. The first time they fall below 50% health, they slip into shadows. Enemies targeting them are redirected to a nearby unit, preferring Tanks.<br>','[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"AD":0.12,"AP":12,"Duration":3,"HealthThreshold":0.5}},{"maxUnits":3,"minUnits":3,"style":3,"variables":{"AD":0.25,"AP":25,"Duration":3,"HealthThreshold":0.5}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"AD":0.4,"AP":40,"Duration":3,"HealthThreshold":0.5}},{"maxUnits":25000,"minUnits":5,"style":4,"variables":{"AD":0.55,"AP":55,"Duration":3,"HealthThreshold":0.5}}]','{"apiName":"TFT17_AssassinTrait","desc":"Rogues gain Attack Damage and Ability Power. The first time they fall below 50% health, they slip into shadows. Enemies targeting them are redirected to a nearby unit, preferring Tanks.<br>","effects":[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"AD":0.12,"AP":12,"Duration":3,"HealthThreshold":0.5}},{"maxUnits":3,"minUnits":3,"style":3,"variables":{"AD":0.25,"AP":25,"Duration":3,"HealthThreshold":0.5}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"AD":0.4,"AP":40,"Duration":3,"HealthThreshold":0.5}},{"maxUnits":25000,"minUnits":5,"style":4,"variables":{"AD":0.55,"AP":55,"Duration":3,"HealthThreshold":0.5}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Rogue.TFT_Set17.tex","name":"Rogue","org":{"desc":"Rogues gain Attack Damage and Ability Power. The first time they fall below @HealthThreshold*100@% health, they slip into shadows. Enemies targeting them are redirected to a nearby unit, preferring Tanks.<br><br><row>(@MinUnits@) @AP@% %i:scaleAD% %i:scaleAP%</row><br><row>(@MinUnits@) @AP@% %i:scaleAD% %i:scaleAP%</row><br><row>(@MinUnits@) @AP@% %i:scaleAD% %i:scaleAP%</row><br><row>(@MinUnits@) @AP@% %i:scaleAD% %i:scaleAP%</row>","effects":[{"maxUnits":2,"minUnits":2,"style":1,"v