INSERT INTO "traits" VALUES('TFT17_DarkStar','17.1b','Dark Star','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_DarkStar.TFT_Set17.tex','Dark Star units create a black hole that devours enemies below 10% max Health. The higher the trait tier, the stronger the black hole becomes.','[{"maxUnits":3,"minUnits":2,"style":1,"variables":{"ADAP":45,"ExecuteHPPercent":0.08,"PercentHealth":0.3,"SupermassivePercentBonus":0.85}},{"maxUnits":5,"minUnits":4,"style":3,"variables":{"ADAP":45,"ExecuteHPPercent":0.08,"PercentHealth":0.3,"SupermassivePercentBonus":0.85}},{"maxUnits":8,"minUnits":6,"style":4,"variables":{"ADAP":45,"ExecuteHPPercent":0.08,"PercentHealth":0.3,"SupermassivePercentBonus":0.85}},{"maxUnits":25000,"minUnits":9,"style":6,"variables":{"ADAP":45,"ExecuteHPPercent":0.08,"PercentHealth":0.3,"SupermassivePercentBonus":0.85}}]','{"apiName":"TFT17_DarkStar","desc":"Dark Star units create a black hole that devours enemies below 10% max Health. The higher the trait tier, the stronger the black hole becomes.","effects":[{"maxUnits":3,"minUnits":2,"style":1,"variables":{"ADAP":45,"ExecuteHPPercent":0.08,"PercentHealth":0.3,"SupermassivePercentBonus":0.85}},{"maxUnits":5,"minUnits":4,"style":3,"variables":{"ADAP":45,"ExecuteHPPercent":0.08,"PercentHealth":0.3,"SupermassivePercentBonus":0.85}},{"maxUnits":8,"minUnits":6,"style":4,"variables":{"ADAP":45,"ExecuteHPPercent":0.08,"PercentHealth":0.3,"SupermassivePercentBonus":0.85}},{"maxUnits":25000,"minUnits":9,"style":6,"variables":{"ADAP":45,"ExecuteHPPercent":0.08,"PercentHealth":0.3,"SupermassivePercentBonus":0.85}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_DarkStar.TFT_Set17.tex","name":"Dark Star","org":{"desc":"<row>(@MinUnits@) Dark Stars create a black hole that consumes enemies at @ExecuteHPPercent*100@% max health.</row><br><row>(@MinUnits@) AND they gain @ADAP@% %i:scaleAD%%i:scaleAP%.</row><br><row>(@MinUnits@) AND the strongest Dark Star unit goes supermassive, gaining @SupermassivePercentBonus*100@% effectiveness from Dark Star, and creates 2 minor Black Holes.</row><br><row>(@MinUnits@) All Dark Stars are supermassive. At level 10, CONSUME EVERYONE. </row>","effects":[{"maxUnits":3,"minUnits":2,"style":1,"variables":{"ADAP":45,"ExecuteHPPercent":0.07999999821186066,"PercentHealth":0.30000001192092896,"SupermassivePercentBonus":0.8500000238418579}},{"maxUnits":5,"minUnits":4,"style":3,"variables":{"ADAP":45,"ExecuteHPPercent":0.07999999821186066,"PercentHealth":0.30000001192092896,"SupermassivePercentBonus":0.8500000238418579}},{"maxUnits":8,"minUnits":6,"style":5,"variables":{"ADAP":45,"ExecuteHPPercent":0.07999999821186066,"PercentHealth":0.30000001192092896,"SupermassivePercentBonus":0.8500000238418579}},{"maxUnits":25000,"minUnits":9,"style":6,"variables":{"ADAP":45,"ExecuteHPPercent":0.07999999821186066,"PercentHealth":0.30000001192092896,"SupermassivePercentBonus":0.8500000238418579}}]},"_key":"TFT17_DarkStar","level":{"2":"Dark Stars create a black hole that consumes enemies at 8% max health.","4":"AND they gain 45% %i:scaleAD%%i:scaleAP%.","6":"AND the strongest Dark Star unit goes supermassive, gaining 85% effectiveness from Dark Star, and creates 2 minor Black Holes.","9":"All Dark Stars are supermassive. At level 10, CONSUME EVERYONE."},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_DarkStar.TFT_Set17.png","champions":[{"apiName":"TFT17_Kaisa","name":"Kai''Sa"},{"apiName":"TFT17_Karma","name":"Karma"},{"apiName":"TFT17_Jhin","name":"Jhin"},{"apiName":"TFT17_Chogath","name":"Cho''Gath"},{"apiName":"TFT17_Lissandra","name":"Lissandra"},{"apiName":"TFT17_Mordekaiser","name":"Mordekaiser"}],"category":"origin","removeSpaceName":"DarkStar"}');
INSERT INTO "traits" VALUES('TFT17_Primordian','17.1b','Primordian','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Primordian.TFT_Set17.tex','','[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"DamageMultiplier":1,"DamageTakenPercentModifier":0.08,"PercentMoreSwarmlings":45,"undefined":6}},{"maxUnits":25000,"minUnits":3,"style":4,"variables":{"DamageMultiplier":1.45,"DamageTakenPercentModifier":0.08,"PercentMoreSwarmlings":45,"undefined":6}}]','{"apiName":"TFT17_Primordian","desc":"","effects":[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"DamageMultiplier":1,"DamageTakenPercentModifier":0.08,"PercentMoreSwarmlings":45,"undefined":6}},{"maxUnits":25000,"minUnits":3,"style":4,"variables":{"DamageMultiplier":1.45,"DamageTakenPercentModifier":0.08,"PercentMoreSwarmlings":45,"undefined":6}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Primordian.TFT_Set17.tex","name":"Primordian","org":{"desc":"<row>(@MinUnits@) Dealing damage spawns Swarmlings based on unique Primordian star level.</row><br><row>(@MinUnits@) Spawn @PercentMoreSwarmlings@% more Swarmlings! After each player combat, gain a random 1 or 2-cost champion. </row><br><br><rules>@DamageTakenPercentModifier*100@% of damage taken contributes to damage dealt.</rules>","effects":[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"DamageMultiplier":1,"DamageTakenPercentModifier":0.07999999821186066,"PercentMoreSwarmlings":45,"{3ed71f24}":6}},{"maxUnits":25000,"minUnits":3,"style":5,"variables":{"DamageMultiplier":1.4500000476837158,"DamageTakenPercentModifier":0.07999999821186066,"PercentMoreSwarmlings":45,"{3ed71f24}":6}}]},"_key":"TFT17_Primordian","level":{"2":"Dealing damage spawns Swarmlings based on unique Primordian star level.","3":"Spawn 45% more Swarmlings! After each player combat, gain a random 1 or 2-cost champion."},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_Primordian.TFT_Set17.png","champions":[{"apiName":"TFT17_Briar","name":"Briar"},{"apiName":"TFT17_Belveth","name":"Bel''Veth"},{"apiName":"TFT17_RekSai","name":"Rek''Sai"}],"category":"origin","removeSpaceName":"Primordian"}');
INSERT INTO "traits" VALUES('TFT17_SpaceGroove','17.1b','Space Groove','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_SpaceGroove.TFT_Set17.tex','Space Groove units can enter the Groove state. While in Groove, their bonuses scale with the number of Space Groove allies and grow stronger at higher trait tiers.','[{"maxUnits":2,"minUnits":1,"style":1,"variables":{"ADAPPerSecond":null,"EffectBonus":null,"StartOfCombatDuration":null}},{"maxUnits":4,"minUnits":3,"style":3,"variables":{"ADAPPerSecond":null,"EffectBonus":null,"StartOfCombatDuration":3}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"ADAPPerSecond":5,"EffectBonus":null,"StartOfCombatDuration":3}},{"maxUnits":9,"minUnits":7,"style":4,"variables":{"ADAPPerSecond":5,"EffectBonus":10,"StartOfCombatDuration":3}},{"maxUnits":25000,"minUnits":10,"style":5,"variables":{"ADAPPerSecond":10,"EffectBonus":500,"StartOfCombatDuration":60,"undefined":1500}}]','{"apiName":"TFT17_SpaceGroove","desc":"Space Groove units can enter the Groove state. While in Groove, their bonuses scale with the number of Space Groove allies and grow stronger at higher trait tiers.","effects":[{"maxUnits":2,"minUnits":1,"style":1,"variables":{"ADAPPerSecond":null,"EffectBonus":null,"StartOfCombatDuration":null}},{"maxUnits":4,"minUnits":3,"style":3,"variables":{"ADAPPerSecond":null,"EffectBonus":null,"StartOfCombatDuration":3}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"ADAPPerSecond":5,"EffectBonus":null,"StartOfCombatDuration":3}},{"maxUnits":9,"minUnits":7,"style":4,"variables":{"ADAPPerSecond":5,"EffectBonus":10,"StartOfCombatDuration":3}},{"maxUnits":25000,"minUnits":10,"style":5,"variables":{"ADAPPerSecond":10,"EffectBonus":500,"StartOfCombatDuration":60,"undefined":1500}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_SpaceGroove.TFT_Set17.tex","name":"Space Groove","org":{"desc":"<row>(@MinUnits@) Groovians can enter {{TFT17_SpaceGroove_TheGroove}}. While in it, they gain Attack Speed and max Health Regen, increased per Groovian on your team.</row><br><row>(@MinUnits@) All Groovians start combat in {{TFT17_SpaceGroove_TheGroove}} for @StartOfCombatDuration@ seconds.</row><br><row>(@MinUnits@) Each second spent in {{TFT17_SpaceGroove_TheGroove}} grants @ADAPPerSecond@% stacking Attack Damage and Ability Power.</row><br><row>(@MinUnits@) Increase these effects by @EffectBonus@%!</row><br><row>(@MinUnits@) {{TFT17_SpaceGroove_Groove}}</row><br><br>{{TFT17_SpaceGroove_TheGroove}}: @TFTUnitProperty.:TFT17_SpaceGroove_AS*100@% %i:scaleAS%, @TFTUnitProperty.:TFT17_SpaceGroove_HealthRegen*100@% %i:scaleHPRegen%","effects":[{"maxUnits":2,"minUnits":1,"style":1,"variables":{"ADAPPerSecond":null,"EffectBonus":null,"StartOfCombatDuration":null}},{"maxUnits":4,"minUnits":3,"style":3,"variables":{"ADAPPerSecond":null,"EffectBonus":null,"StartOfCombatDuration":3}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"ADAPPerSecond":5,"EffectBonus":null,"StartOfCombatDuration":3}},{"maxUnits":9,"minUnits":7,"style":5,"variables":{"ADAPPerSecond":5,"EffectBonus":10,"StartOfCombatDuration":3}},{"maxUnits":25000,"minUnits":10,"style":6,"variables":{"ADAPPerSecond":10,"EffectBonus":500,"StartOfCombatDuration":60,"{32ed1fda}":800,"{3e46e556}":1500}}]},"_key":"TFT17_SpaceGroove","level":{"1":"Groovians can enter Space Groove. While in it, they gain Attack Speed and max Health Regen, increased per Groovian on your team.","3":"All Groovians start combat in Space Groove for 3 seconds.","5":"Each second spent in Space Groove grants 5% stacking Attack Damage and Ability Power.","7":"Increase these effects by 10%!","10":"{{TFT17_SpaceGroove_Groove}}"},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_SpaceGroove.TFT_Set17.png","champions":[{"apiName":"TFT17_Teemo","name":"Teemo"},{"apiName":"TFT17_Nasus","name":"Nasus"},{"apiName":"TFT17_Gwen","name":"Gwen"},{"apiName":"TFT17_Samira","name":"Samira"},{"apiName":"TFT17_Ornn","name":"Ornn"},{"apiName":"TFT17_Nami","name":"Nami"},{"apiName":"TFT17_Blitzc