INSERT INTO "traits" VALUES('TFT17_ADMIN','17.1b','Arbiter','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Arbiter.TFT_Set17.tex','Scribe a unique divine law, allowing you to choose an effect to apply to Arbiters when a chosen cause occurs.<br>','[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"DamageInstances":10,"HealthThreshold":0.4,"ManaToSpend":50,"NumAttacks":3,"NumSeconds":4,"ShieldDuration":4,"-":1}},{"maxUnits":25000,"minUnits":3,"style":4,"variables":{"DamageInstances":10,"HealthThreshold":0.4,"ManaToSpend":50,"NumAttacks":3,"NumSeconds":4,"ShieldDuration":4,"-":1}}]','{"apiName":"TFT17_ADMIN","desc":"Scribe a unique divine law, allowing you to choose an effect to apply to Arbiters when a chosen cause occurs.<br>","effects":[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"DamageInstances":10,"HealthThreshold":0.4,"ManaToSpend":50,"NumAttacks":3,"NumSeconds":4,"ShieldDuration":4,"-":1}},{"maxUnits":25000,"minUnits":3,"style":4,"variables":{"DamageInstances":10,"HealthThreshold":0.4,"ManaToSpend":50,"NumAttacks":3,"NumSeconds":4,"ShieldDuration":4,"-":1}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Arbiter.TFT_Set17.tex","name":"Arbiter","org":{"desc":"Scribe a unique divine law, allowing you to choose an effect to apply to Arbiters when a chosen cause occurs.<br><br><row>(@MinUnits@) Choose a cause and effect for your law</row><br><row>(@MinUnits@) Effects are stronger. </row>","effects":[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"DamageInstances":10,"HealthThreshold":0.4000000059604645,"ManaToSpend":50,"NumAttacks":3,"NumSeconds":4,"ShieldDuration":4,"{fefec6fb}":1}},{"maxUnits":25000,"minUnits":3,"style":5,"variables":{"DamageInstances":10,"HealthThreshold":0.4000000059604645,"ManaToSpend":50,"NumAttacks":3,"NumSeconds":4,"ShieldDuration":4,"{fefec6fb}":1}}]},"_key":"TFT17_ADMIN","level":{"2":"Choose a cause and effect for your law","3":"Effects are stronger."},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_Arbiter.TFT_Set17.png","champions":[{"apiName":"TFT17_Leona","name":"Leona"},{"apiName":"TFT17_Zoe","name":"Zoe"},{"apiName":"TFT17_Diana","name":"Diana"},{"apiName":"TFT17_Leblanc","name":"LeBlanc"}],"category":"origin","removeSpaceName":"Arbiter"}');
INSERT INTO "traits" VALUES('TFT17_Stargazer_Mountain','17.1b','Stargazer (The Mountain)','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex','Stargazers chart a different constellation every game. This game: <TFTStargazer>The Mountain</TFTStargazer><br><br>Every 5 player combats, gain a Stargazer Emblem. Stargazers in empowered hexes gain various bonuses.<br><br>(Combats Remaining:&nbsp;@TFTUnitProperty.trait:TFT17_Stargazer_Mountain_CombatsRemaining@)<br>','[{"maxUnits":3,"minUnits":3,"style":1,"variables":{"Mountain_ADAP":null,"Mountain_AS":null,"Mountain_DR":null,"Mountain_Health":0.15,"Mountain_Resists":null,"Mountain_RoundsPerEmblem":5,"Mountain_StatIncrease":null,"undefined":null}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"Mountain_ADAP":0.15,"Mountain_AS":null,"Mountain_DR":null,"Mountain_Health":0.15,"Mountain_Resists":null,"Mountain_RoundsPerEmblem":5,"Mountain_StatIncrease":null,"undefined":null}},{"maxUnits":5,"minUnits":5,"style":3,"variables":{"Mountain_ADAP":0.15,"Mountain_AS":null,"Mountain_DR":null,"Mountain_Health":0.15,"Mountain_Resists":10,"Mountain_RoundsPerEmblem":5,"Mountain_StatIncrease":null,"undefined":null}},{"maxUnits":6,"minUnits":6,"style":3,"variables":{"Mountain_ADAP":0.15,"Mountain_AS":0.1,"Mountain_DR":null,"Mountain_Health":0.15,"Mountain_Resists":10,"Mountain_RoundsPerEmblem":5,"Mountain_StatIncrease":null,"undefined":null}},{"maxUnits":7,"minUnits":7,"style":3,"variables":{"Mountain_ADAP":0.15,"Mountain_AS":0.1,"Mountain_DR":0.06,"Mountain_Health":0.15,"Mountain_Resists":10,"Mountain_RoundsPerEmblem":5,"Mountain_StatIncrease":null,"undefined":null}},{"maxUnits":8,"minUnits":8,"style":4,"variables":{"Mountain_ADAP":0.15,"Mountain_AS":0.1,"Mountain_DR":0.06,"Mountain_Health":0.15,"Mountain_Resists":10,"Mountain_RoundsPerEmblem":5,"Mountain_StatIncrease":0.1,"undefined":null}},{"maxUnits":9,"minUnits":9,"style":4,"variables":{"Mountain_ADAP":0.15,"Mountain_AS":0.1,"Mountain_DR":0.06,"Mountain_Health":0.15,