INSERT INTO "traits" VALUES('TFT17_ResistTank','17.1b','Bastion','class','ASSETS/UX/TraitIcons/Trait_Icon_9_Bastion.tex','Your team gains 15 Armor and Magic Resist.<br><br>Bastions gain more, and the value doubles in the first 10 seconds of combat.<br>','[{"maxUnits":3,"minUnits":2,"style":1,"variables":{"BonusArmor":16,"BonusMR":16,"Duration":10,"EnhancedTeamwideArmor":20,"StatMultiplier":2,"TeamwideResists":15}},{"maxUnits":5,"minUnits":4,"style":3,"variables":{"BonusArmor":40,"BonusMR":40,"Duration":10,"EnhancedTeamwideArmor":20,"StatMultiplier":2,"TeamwideResists":15}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"BonusArmor":60,"BonusMR":60,"Duration":10,"EnhancedTeamwideArmor":20,"StatMultiplier":2,"TeamwideResists":15}}]','{"apiName":"TFT17_ResistTank","desc":"Your team gains 15 Armor and Magic Resist.<br><br>Bastions gain more, and the value doubles in the first 10 seconds of combat.<br>","effects":[{"maxUnits":3,"minUnits":2,"style":1,"variables":{"BonusArmor":16,"BonusMR":16,"Duration":10,"EnhancedTeamwideArmor":20,"StatMultiplier":2,"TeamwideResists":15}},{"maxUnits":5,"minUnits":4,"style":3,"variables":{"BonusArmor":40,"BonusMR":40,"Duration":10,"EnhancedTeamwideArmor":20,"StatMultiplier":2,"TeamwideResists":15}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"BonusArmor":60,"BonusMR":60,"Duration":10,"EnhancedTeamwideArmor":20,"StatMultiplier":2,"TeamwideResists":15}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_9_Bastion.tex","name":"Bastion","org":{"desc":"Your team gains @TeamwideResists@ Armor and Magic Resist.<br><br>Bastions gain more, and the value doubles in the first @Duration@ seconds of combat.<br><br><row>(@MinUnits@) @BonusArmor@ %i:scaleArmor%%i:scaleMR%</row><br><row>(@MinUnits@) @BonusArmor@ %i:scaleArmor%%i:scaleMR%</row><br><row>(@MinUnits@) @BonusArmor@ %i:scaleArmor%%i:scaleMR%; Non-Bastions gain an additional @EnhancedTeamwideArmor@ %i:scaleArmor%%i:scaleMR%.</row>","effects":[{"maxUnits":3,"minUnits":2,"style":1,"variables":{"BonusArmor":16,"BonusMR":16,"Duration":10,"EnhancedTeamwideArmor":20,"StatMultiplier":2,"TeamwideResists":15}},{"maxUnits":5,"minUnits":4,"style":3,"variables":{"BonusArmor":40,"BonusMR":40,"Duration":10,"EnhancedTeamwideArmor":20,"StatMultiplier":2,"TeamwideResists":15}},{"maxUnits":25000,"minUnits":6,"style":5,"variables":{"BonusArmor":60,"BonusMR":60,"Duration":10,"EnhancedTeamwideArmor":20,"StatMultiplier":2,"TeamwideResists":15}}]},"_key":"TFT17_ResistTank","level":{"2":"16 %i:scaleArmor%%i:scaleMR%","4":"40 %i:scaleArmor%%i:scaleMR%","6":"60 %i:scaleArmor%%i:scaleMR%; Non-Bastions gain an additional 20 %i:scaleArmor%%i:scaleMR%."},"imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_9_Bastion.png","champions":[{"apiName":"TFT17_Rammus","name":"Rammus"},{"apiName":"TFT17_Poppy","name":"Poppy"},{"apiName":"TFT17_Aatrox","name":"Aatrox"},{"apiName":"TFT17_Ornn","name":"Ornn"},{"apiName":"TFT17_Jax","name":"Jax"},{"apiName":"TFT17_Shen","name":"Shen"}],"category":"class","removeSpaceName":"Bastion"}');
INSERT INTO "traits" VALUES('TFT17_Astronaut','17.1b','Meeple','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Astronaut.TFT_Set17.tex','Meeple attract Meeps that empower Meeple abilities in meepy ways. They also gain bonus Health.<br>','[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"BonusHealth":100,"Meeps":2}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"BonusHealth":400,"Meeps":3}},{"maxUnits":9,"minUnits":7,"style":4,"variables":{"BonusHealth":400,"Meeps":4}},{"maxUnits":25000,"minUnits":10,"style":5,"variables":{"BonusHealth":500,"Meeps":6}}]','{"apiName":"TFT17_Astronaut","desc":"Meeple attract Meeps that empower Meeple abilities in meepy ways. They also gain bonus Health.<br>","effects":[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"BonusHealth":100,"Meeps":2}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"BonusHealth":400,"Meeps":3}},{"maxUnits":9,"minUnits":7,"style":4,"variables":{"BonusHealth":400,"Meeps":4}},{"maxUnits":25000,"minUnits":10,"style":5,"variables":{"BonusHealth":500,"Meeps":6}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Astronaut.TFT_Set17.tex","name":"Meeple","org":{"desc":"Meeple attract Meeps that empower Meeple abilities in meepy ways. They also gain bonus Health.<br><br><row>(@MinUnits@) @Meeps@ %i:set14AmpIcon%, @BonusHealth@ %i:scaleHealth%</row><br><row>(@MinUnits@) @Meeps@ %i:set14AmpIcon%, @BonusHealth@ %i:scaleHealth%</row><br><row>(@MinUnits@) @Meeps@ %i:set14AmpIcon%, @BonusHealth@ %i:scaleHealth%. Create a Cloning Slot on your bench. Gain gold and a 1-star copy of the champion placed there when cloning completes.</row><br><row>(@MinUnits@) @Meeps@ %i:set14AmpIcon%, @BonusHealth@ %i:scaleHealth%. SUMMON THE FOUR MEEPLORDS!</row><br><br><rules>Cloning time = Champion cost</rules>","effects":[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"BonusHealth":100,"Meeps":2}},{"maxUnits":6,"minUnits":5,"style":3,"variables":{"BonusHealth":400,"Meeps":3}},{"maxUnits":9,"minUnits":7,"style":5,"variables":{"BonusHealth