INSERT INTO "traits" VALUES('TFT17_BlitzcrankUniqueTrait','17.1b','Party Animal','class','ASSETS/UX/TraitIcons/Trait_Icon_17_PartyAnimal.TFT_Set17.tex','Once per combat, after falling below 45% percent Health, become untargetable and repair 15% max Health per second. Upon reaching full Health, or when no other allies remain, return to combat. If fully healed, for the rest of combat Blitzcrank is in Space Groove and Party Crasher''s passive fires bolts four times as fast.','[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"HealthThreshold":0.45,"PercentHealthHeal":0.15}}]','{"apiName":"TFT17_BlitzcrankUniqueTrait","desc":"Once per combat, after falling below 45% percent Health, become untargetable and repair 15% max Health per second. Upon reaching full Health, or when no other allies remain, return to combat. If fully healed, for the rest of combat Blitzcrank is in Space Groove and Party Crasher''s passive fires bolts four times as fast.","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"HealthThreshold":0.45,"PercentHealthHeal":0.15}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_PartyAnimal.TFT_Set17.tex","name":"Party Animal","org":{"desc":"Once per combat, after falling below @HealthThreshold*100@% percent Health, become untargetable and repair @PercentHealthHeal*100@% max Health per second. Upon reaching full Health, or when no other allies remain, return to combat. If fully healed, for the rest of combat Blitzcrank is in {{TFT17_SpaceGroove_TheGroove}} and Party Crasher''s passive fires bolts four times as fast.","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"HealthThreshold":0.44999998807907104,"PercentHealthHeal":0.15000000596046448}}]},"_key":"TFT17_BlitzcrankUniqueTrait","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_PartyAnimal.TFT_Set17.png","champions":[{"apiName":"TFT17_Blitzcrank","name":"Blitzcrank"}],"category":"class","removeSpaceName":"PartyAnimal"}');
